import{g as a,o as n,c as l,al as o}from"./chunks/framework.CrxCEdOb.js";const v=JSON.parse('{"title":"04 容器语法","description":"8 种 Rspress 风格容器的写法、嵌套规则，以及 prompt 卡片和分步说明。","frontmatter":{"title":"04 容器语法","description":"8 种 Rspress 风格容器的写法、嵌套规则，以及 prompt 卡片和分步说明。"},"headers":[],"relativePath":"notes/writing-guide/04-containers.md","filePath":"notes/writing-guide/04-containers.md","lastUpdated":1793364501000}'),p={name:"notes/writing-guide/04-containers.md"};function r(t,s,e,i,c,d){return n(),l("div",null,[...s[0]||(s[0]=[o(`<h1 id="容器语法" tabindex="-1">容器语法 <a class="header-anchor" href="#容器语法" aria-label="Permalink to &quot;容器语法&quot;">​</a></h1><p>项目注册了 8 种 Rspress 风格容器。下面每一个都是真实效果，不是截图；写法收在各自的可折叠块里。</p><div class="rp-callout rp-callout--note"><div class="rp-callout__title">Note</div><div class="rp-callout__content"><p>备注用 note：补一句背景，不打断正文。</p></div></div><div class="rp-callout rp-callout--tip"><div class="rp-callout__title">Tip</div><div class="rp-callout__content"><p>提示用 tip：技巧、捷径、个人经验。</p></div></div><div class="rp-callout rp-callout--important"><div class="rp-callout__title">Important</div><div class="rp-callout__content"><p>重要用 important：不能跳过的前提条件。</p></div></div><div class="rp-callout rp-callout--info"><div class="rp-callout__title">Info</div><div class="rp-callout__content"><p>补充信息用 info：参数、版本、链接。</p></div></div><div class="rp-callout rp-callout--warning"><div class="rp-callout__title">Warning</div><div class="rp-callout__content"><p>警告用 warning：容易踩坑，但后果可控。</p></div></div><div class="rp-callout rp-callout--danger"><div class="rp-callout__title">Danger</div><div class="rp-callout__content"><p>危险用 danger：会导致数据丢失或部署失败的操作。</p></div></div><div class="rp-callout rp-callout--caution"><div class="rp-callout__title">Caution</div><div class="rp-callout__content"><p>注意用 caution：配色同 danger，语气稍轻。</p></div></div><details class="rp-callout rp-callout--details"><summary class="rp-callout__title">点开看 details</summary><div class="rp-callout__content"><p>可折叠内容，适合长代码、补充材料。</p></div></details><details class="rp-callout rp-callout--details"><summary class="rp-callout__title">查看这 8 种容器的写法</summary><div class="rp-callout__content"><div class="language-md"><button title="Copy Code" class="copy"></button><span class="lang">md</span><pre class="shiki css-variables vp-code" tabindex="0"><code><span class="line"></span>
<span class="line"><span style="color:var(--shiki-foreground);">:::note</span></span>
<span class="line"><span style="color:var(--shiki-foreground);">备注用 note。</span></span>
<span class="line"><span style="color:var(--shiki-foreground);">:::</span></span>
<span class="line"></span>
<span class="line"><span style="color:var(--shiki-foreground);">:::tip 自定义标题</span></span>
<span class="line"><span style="color:var(--shiki-foreground);">类型名后面空一格，直接写标题。</span></span>
<span class="line"><span style="color:var(--shiki-foreground);">:::</span></span>
<span class="line"></span>
<span class="line"><span style="color:var(--shiki-foreground);">:::tip{title=&quot;</span><span style="color:var(--shiki-foreground);font-weight:bold;">**标题也能写 markdown**</span><span style="color:var(--shiki-foreground);">&quot;}</span></span>
<span class="line"><span style="color:var(--shiki-foreground);">也可以用 {title=&quot;…&quot;}。</span></span>
<span class="line"><span style="color:var(--shiki-foreground);">:::</span></span>
<span class="line"></span>
<span class="line"><span style="color:var(--shiki-foreground);">:::important</span></span>
<span class="line"><span style="color:var(--shiki-foreground);">重要内容。</span></span>
<span class="line"><span style="color:var(--shiki-foreground);">:::</span></span>
<span class="line"></span>
<span class="line"><span style="color:var(--shiki-foreground);">:::info</span></span>
<span class="line"><span style="color:var(--shiki-foreground);">补充信息。</span></span>
<span class="line"><span style="color:var(--shiki-foreground);">:::</span></span>
<span class="line"></span>
<span class="line"><span style="color:var(--shiki-foreground);">:::warning</span></span>
<span class="line"><span style="color:var(--shiki-foreground);">警告内容。</span></span>
<span class="line"><span style="color:var(--shiki-foreground);">:::</span></span>
<span class="line"></span>
<span class="line"><span style="color:var(--shiki-foreground);">:::danger</span></span>
<span class="line"><span style="color:var(--shiki-foreground);">危险操作。</span></span>
<span class="line"><span style="color:var(--shiki-foreground);">:::</span></span>
<span class="line"></span>
<span class="line"><span style="color:var(--shiki-foreground);">:::caution</span></span>
<span class="line"><span style="color:var(--shiki-foreground);">注意事项。</span></span>
<span class="line"><span style="color:var(--shiki-foreground);">:::</span></span>
<span class="line"></span>
<span class="line"><span style="color:var(--shiki-foreground);">:::details 折叠标题</span></span>
<span class="line"><span style="color:var(--shiki-foreground);">默认收起的内容。</span></span>
<span class="line"><span style="color:var(--shiki-foreground);">:::</span></span></code></pre></div></div></details><h2 id="标题的两种写法" tabindex="-1">标题的两种写法 <a class="header-anchor" href="#标题的两种写法" aria-label="Permalink to &quot;标题的两种写法&quot;">​</a></h2><ul><li><code>:::tip 自定义标题</code>：空格后直接写，标题按纯文本渲染。</li><li><code>:::tip{title=&quot;**标题也能写 markdown**&quot;}</code>：可以塞 markdown，加粗、链接都行。</li></ul><div class="rp-callout rp-callout--warning"><div class="rp-callout__title"><code>:::</code> 后面不要紧跟中文</div><div class="rp-callout__content"><p><code>:::提示</code> 这种写法不会生效，会被当成普通段落。类型名和标题之间必须有空格，或者改用 <code>{title=&quot;…&quot;}</code>。</p></div></div><h2 id="嵌套" tabindex="-1">嵌套 <a class="header-anchor" href="#嵌套" aria-label="Permalink to &quot;嵌套&quot;">​</a></h2><p>外层比内层多用一个冒号，否则内层会被提前闭合。下面是真实嵌套效果：</p><div class="rp-callout rp-callout--warning"><div class="rp-callout__title">Warning</div><div class="rp-callout__content"><p>外层 warning，里面套一个 note：</p><div class="rp-callout rp-callout--note"><div class="rp-callout__title">Note</div><div class="rp-callout__content"><p>内层 note。外层用四个冒号，内层用三个。</p></div></div></div></div><details class="rp-callout rp-callout--details"><summary class="rp-callout__title">查看嵌套写法</summary><div class="rp-callout__content"><div class="language-md"><button title="Copy Code" class="copy"></button><span class="lang">md</span><pre class="shiki css-variables vp-code" tabindex="0"><code><span class="line"><span style="color:var(--shiki-foreground);">::::warning</span></span>
<span class="line"><span style="color:var(--shiki-foreground);">外层 warning</span></span>
<span class="line"></span>
<span class="line"><span style="color:var(--shiki-foreground);">:::note</span></span>
<span class="line"><span style="color:var(--shiki-foreground);">内层 note</span></span>
<span class="line"><span style="color:var(--shiki-foreground);">:::</span></span>
<span class="line"></span>
<span class="line"><span style="color:var(--shiki-foreground);">::::</span></span></code></pre></div></div></details><h2 id="prompt-卡片" tabindex="-1">Prompt 卡片 <a class="header-anchor" href="#prompt-卡片" aria-label="Permalink to &quot;Prompt 卡片&quot;">​</a></h2><p>逐字保留换行、反引号和缩进，右上角带复制按钮，适合放给 AI 的提示词：</p><div class="rp-prompt" style="--rp-prompt-accent:#6366F1;"><div class="rp-prompt__backdrop"></div><div class="rp-prompt__panel"><div class="rp-prompt__header"><div class="rp-prompt__meta"><span class="rp-prompt__eyebrow"><span class="rp-prompt__icon" title="Codex"><svg aria-hidden="true" viewBox="0 0 24 24" xmlns="http://www.w3.org/2000/svg"><path d="M19.503 0H4.496A4.496 4.496 0 000 4.496v15.007A4.496 4.496 0 004.496 24h15.007A4.496 4.496 0 0024 19.503V4.496A4.496 4.496 0 0019.503 0z" fill="#fff"></path><path d="M9.064 3.344a4.578 4.578 0 012.285-.312c1 .115 1.891.54 2.673 1.275.01.01.024.017.037.021a.09.09 0 00.043 0 4.55 4.55 0 013.046.275l.047.022.116.057a4.581 4.581 0 012.188 2.399c.209.51.313 1.041.315 1.595a4.24 4.24 0 01-.134 1.223.123.123 0 00.03.115c.594.607.988 1.33 1.183 2.17.289 1.425-.007 2.71-.887 3.854l-.136.166a4.548 4.548 0 01-2.201 1.388.123.123 0 00-.081.076c-.191.551-.383 1.023-.74 1.494-.9 1.187-2.222 1.846-3.711 1.838-1.187-.006-2.239-.44-3.157-1.302a.107.107 0 00-.105-.024c-.388.125-.78.143-1.204.138a4.441 4.441 0 01-1.945-.466 4.544 4.544 0 01-1.61-1.335c-.152-.202-.303-.392-.414-.617a5.81 5.81 0 01-.37-.961 4.582 4.582 0 01-.014-2.298.124.124 0 00.006-.056.085.085 0 00-.027-.048 4.467 4.467 0 01-1.034-1.651 3.896 3.896 0 01-.251-1.192 5.189 5.189 0 01.141-1.6c.337-1.112.982-1.985 1.933-2.618.212-.141.413-.251.601-.33.215-.089.43-.164.646-.227a.098.098 0 00.065-.066 4.51 4.51 0 01.829-1.615 4.535 4.535 0 011.837-1.388zm3.482 10.565a.637.637 0 000 1.272h3.636a.637.637 0 100-1.272h-3.636zM8.462 9.23a.637.637 0 00-1.106.631l1.272 2.224-1.266 2.136a.636.636 0 101.095.649l1.454-2.455a.636.636 0 00.005-.64L8.462 9.23z" fill="#6366F1"></path></svg></span>For your Agent</span></div><div class="rp-prompt__header-row"><div class="rp-prompt__header-left"><div class="rp-prompt__title-with-icon"><div class="rp-prompt__title">一键创建项目</div></div><p class="rp-prompt__description">复制后发给 Agent</p></div><div class="rp-prompt__header-actions"><button type="button" class="rp-prompt__action-copy" title="复制 Prompt"><svg class="rp-prompt__action-icon" xmlns="http://www.w3.org/2000/svg" width="32" height="32" viewBox="0 0 24 24"><path fill="currentColor" d="M20 8v12H8V8zm0-2H8a2 2 0 0 0-2 2v12a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8a2 2 0 0 0-2-2"></path><path fill="currentColor" d="M4 16H2V4a2 2 0 0 1 2-2h12v2H4Z"></path></svg><span>复制 Prompt</span></button><button type="button" class="rp-prompt__action-toggle" aria-controls="rp-prompt-content-1" aria-expanded="false" title="展开"><svg class="rp-prompt__action-toggle-icon" width="1em" height="1em" viewBox="0 0 32 32"><path fill="currentColor" d="M16 22 6 12l1.4-1.4 8.6 8.6 8.6-8.6L26 12z"></path></svg></button></div></div></div><div id="rp-prompt-content-1" class="rp-prompt__content rp-prompt__content--collapsed" aria-hidden="true"><div class="rp-prompt__content-inner"><div class="rp-prompt__content-body" style="white-space:pre-wrap;">按照官方指南创建项目。 1. 用 \`create rspress@latest\` 初始化。 2. 安装依赖。 3. 启动开发服务器。</div></div></div></div></div><details class="rp-callout rp-callout--details"><summary class="rp-callout__title">查看 prompt 写法</summary><div class="rp-callout__content"><div class="language-md"><button title="Copy Code" class="copy"></button><span class="lang">md</span><pre class="shiki css-variables vp-code" tabindex="0"><code><span class="line"><span style="color:var(--shiki-foreground);">:::prompt{title=&quot;一键创建项目&quot; description=&quot;复制后发给 Agent&quot;}</span></span>
<span class="line"><span style="color:var(--shiki-foreground);">按照官方指南创建项目。</span></span>
<span class="line"></span>
<span class="line"><span style="color:var(--shiki-foreground);">1. 用 </span><span style="color:var(--shiki-token-string);">\`create rspress@latest\`</span><span style="color:var(--shiki-foreground);"> 初始化。</span></span>
<span class="line"><span style="color:var(--shiki-foreground);">2. 安装依赖。</span></span>
<span class="line"><span style="color:var(--shiki-foreground);">:::</span></span></code></pre></div><p>需要按 markdown 渲染、且不要复制按钮时，用 <code>{custom}</code>：</p><div class="language-md"><button title="Copy Code" class="copy"></button><span class="lang">md</span><pre class="shiki css-variables vp-code" tabindex="0"><code><span class="line"><span style="color:var(--shiki-foreground);">:::prompt{custom}</span></span>
<span class="line"><span style="color:var(--shiki-foreground);font-weight:bold;">**hello**</span><span style="color:var(--shiki-foreground);"> world</span></span>
<span class="line"><span style="color:var(--shiki-foreground);">:::</span></span></code></pre></div></div></details><h2 id="分步说明" tabindex="-1">分步说明 <a class="header-anchor" href="#分步说明" aria-label="Permalink to &quot;分步说明&quot;">​</a></h2><p>容器里的 <code>##</code>–<code>######</code> 直属标题会各自变成一步：</p><div class="rp-steps"><h3 id="第一步-准备素材" tabindex="-1">第一步：准备素材 <a class="header-anchor" href="#第一步-准备素材" aria-label="Permalink to &quot;第一步：准备素材&quot;">​</a></h3><p>把视频和封面图放进 <code>docs/public/video/</code>。</p><h3 id="第二步-压缩" tabindex="-1">第二步：压缩 <a class="header-anchor" href="#第二步-压缩" aria-label="Permalink to &quot;第二步：压缩&quot;">​</a></h3><p>先 <code>pnpm video --dry-run</code> 看计划，再正式执行。</p><h3 id="第三步-验证" tabindex="-1">第三步：验证 <a class="header-anchor" href="#第三步-验证" aria-label="Permalink to &quot;第三步：验证&quot;">​</a></h3><p><code>pnpm dev</code> 里点开视频，确认能起播、能拖动。</p></div><details class="rp-callout rp-callout--details"><summary class="rp-callout__title">查看 steps 写法</summary><div class="rp-callout__content"><div class="language-md"><button title="Copy Code" class="copy"></button><span class="lang">md</span><pre class="shiki css-variables vp-code" tabindex="0"><code><span class="line"><span style="color:var(--shiki-foreground);">:::steps</span></span>
<span class="line"></span>
<span class="line"><span style="color:var(--shiki-foreground);font-weight:bold;">### 第一步：准备素材</span></span>
<span class="line"><span style="color:var(--shiki-foreground);">把视频和封面图放进 </span><span style="color:var(--shiki-token-string);">\`docs/public/video/\`</span><span style="color:var(--shiki-foreground);">。</span></span>
<span class="line"></span>
<span class="line"><span style="color:var(--shiki-foreground);font-weight:bold;">### 第二步：压缩</span></span>
<span class="line"><span style="color:var(--shiki-foreground);">先 </span><span style="color:var(--shiki-token-string);">\`pnpm video --dry-run\`</span><span style="color:var(--shiki-foreground);"> 看计划，再正式执行。</span></span>
<span class="line"></span>
<span class="line"><span style="color:var(--shiki-foreground);">:::</span></span></code></pre></div></div></details><div class="rp-callout rp-callout--tip"><div class="rp-callout__title">什么时候用哪种</div><div class="rp-callout__content"><p>一句话的补充用 <code>note</code>/<code>info</code>；会被忽略的前提用 <code>tip</code>/<code>important</code>；会踩坑用 <code>warning</code>；不可逆操作用 <code>danger</code>；长代码和补充材料一律塞进 <code>details</code>，别让正文变成长篇代码墙。</p></div></div>`,27)])])}const h=a(p,[["render",r]]);export{v as __pageData,h as default};
